verification.cmd:
$zipPath = (Resolve-Path 'records/child_call_v8_diagnostic_001/development_bundle.zip').Path
$m = Get-Content 'records/child_call_v8_diagnostic_001/bundle_001/manifest.json' -Raw | ConvertFrom-Json
$z = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
$seen = @()
try {
  foreach ($entry in $z.Entries) {
    if ($entry.FullName.EndsWith('/')) { continue }
    if (-not $entry.FullName.StartsWith('bundle_001/')) { throw 'Unexpected archive prefix' }
    $name = $entry.FullName.Substring(11)
    if ($seen -contains $name) { throw 'Duplicate archive member' }
    $seen += $name
    if ($name -eq 'manifest.json') { $expected = 'b4d7970ca59c07342942584e4752ad8c129c3125e25ecc241e3d76c9ddd1c629' }
    else {
      $item = $m.files.PSObject.Properties[$name]
      if ($null -eq $item) { throw 'Unexpected archive member' }
      $expected = $item.Value.sha256
      if ($entry.Length -ne $item.Value.bytes) { throw 'Archive size mismatch' }
    }
    $stream = $entry.Open()
    try { $actual = (Get-FileHash -InputStream $stream -Algorithm SHA256).Hash.ToLowerInvariant() }
    finally { $stream.Dispose() }
    if ($actual -ne $expected) { throw 'Archive member bytes mismatch' }
  }
  if ($seen.Count -ne 16) { throw 'Archive count mismatch' }
} finally { $z.Dispose() }
[pscustomobject]@{archive=$zipPath; sha256=(Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToLowerInvariant(); bytes=(Get-Item -LiteralPath $zipPath).Length; files_verified=$seen.Count; manifest_sha256='b4d7970ca59c07342942584e4752ad8c129c3125e25ecc241e3d76c9ddd1c629'} | ConvertTo-Json -Compress
